call_eBird = function() {

  let txt = "";  
  let url = "https://api.ebird.org/v2/data/obs/US/recent?back=14&hotspot=true&r=";

  // check for valid hotspts
  let valid_hotspots = results.map(e =&gt; eBird_hotspots[e]);
  let some_valid = valid_hotspots.some(e =&gt; e !== undefined && e !== ' ');
  // console.log(some_valid)

  if (some_valid) { 

    // txt = txt + url + results.map(e =&gt; eBird_hotspots.hotspot_id[eBird_hotspots.fed_land.indexOf(e)])
    txt = txt + url + valid_hotspots

    return fetch(txt, {
      headers: {
        'x-ebirdapitoken': eBird_api_key,
      }
    })
    .then(res =&gt; {
      let bird_sightings = res.json();
      // console.log(bird_sightings);
      return bird_sightings;
    });

  } else { 

    return null

  };

};









